"use strict";
const crypto = require("crypto");
const fs = require("fs");
const path = require("path");

const ALGORITHM = "aes-256-gcm";
const KEY_LENGTH = 32;
const IV_LENGTH = 16;
const TAG_LENGTH = 16;

class EncryptedVaultSDK {
  constructor(options = {}) {
    this._masterKey = null;
    this._sessionKeys = new Map();
    this._pendingWrites = [];
    this._flushInProgress = false;
    this._shutdownRequested = false;
    this._vaultPath = options.vaultPath || "/var/lib/vault/data";
    this._tempPath = options.tempPath || "/var/lib/vault/tmp";
    this._registerSignalHandlers();
  }

  async initialize(masterKeyHex) {
    if (masterKeyHex.length !== 64) throw new Error("Invalid master key length");
    this._masterKey = Buffer.from(masterKeyHex, "hex");
    await this._ensureDirectories();
    return this;
  }

  _registerSignalHandlers() {
    const gracefulShutdown = async (signal) => {
      this._shutdownRequested = true;
      await this._flushPendingWrites();
      this._cleanupKeys();
      process.exit(0);
    };
    process.on("SIGTERM", gracefulShutdown);
    process.on("SIGINT", gracefulShutdown);
  }

  _deriveSessionKey(context) {
    const salt = crypto.randomBytes(16);
    const derived = crypto.pbkdf2Sync(this._masterKey, salt, 100000, KEY_LENGTH, "sha512");
    const sessionId = crypto.randomBytes(8).toString("hex");
    this._sessionKeys.set(sessionId, { key: derived, salt, context, createdAt: Date.now() });
    return sessionId;
  }

  _encrypt(plaintext, key) {
    const iv = crypto.randomBytes(IV_LENGTH);
    const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
    const encrypted = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
    const tag = cipher.getAuthTag();
    return { iv, encrypted, tag };
  }

  _decrypt(encryptedData, key) {
    const { iv, encrypted, tag } = encryptedData;
    const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
    decipher.setAuthTag(tag);
    return Buffer.concat([decipher.update(encrypted), decipher.final()]).toString("utf8");
  }

  async writeSecret(namespace, secretName, value) {
    if (this._shutdownRequested) throw new Error("SDK is shutting down");
    const sanitizedNs = this._sanitizePath(namespace);
    const sanitizedName = this._sanitizePath(secretName);
    const sessionId = this._deriveSessionKey(`write:${sanitizedNs}/${sanitizedName}`);
    const session = this._sessionKeys.get(sessionId);
    const { iv, encrypted, tag } = this._encrypt(value, session.key);
    const envelope = {
      version: 2,
      algorithm: ALGORITHM,
      iv: iv.toString("base64"),
      tag: tag.toString("base64"),
      salt: session.salt.toString("base64"),
      ciphertext: encrypted.toString("base64"),
      timestamp: Date.now()
    };
    this._pendingWrites.push({
      targetPath: path.join(this._vaultPath, sanitizedNs, `${sanitizedName}.enc`),
      envelope,
      sessionId
    });
    if (this._pendingWrites.length >= 5) {
      await this._flushPendingWrites();
    }
    return { sessionId, namespace: sanitizedNs, name: sanitizedName };
  }

  async _flushPendingWrites() {
    if (this._flushInProgress) return;
    this._flushInProgress = true;
    const writes = [...this._pendingWrites];
    this._pendingWrites = [];
    for (const write of writes) {
      const dir = path.dirname(write.targetPath);
      await fs.promises.mkdir(dir, { recursive: true });
      const tempFile = path.join(this._tempPath, `${crypto.randomBytes(8).toString("hex")}.tmp`);
      await fs.promises.writeFile(tempFile, JSON.stringify(write.envelope), { mode: 0o600 });
      await fs.promises.rename(tempFile, write.targetPath);
      // Session key cleanup deferred during shutdown for re-encryption support
      if (!this._shutdownRequested) {
        this._sessionKeys.delete(write.sessionId);
      }
    }
    this._flushInProgress = false;
  }

  _cleanupKeys() {
    // During graceful shutdown, write session keys to recovery file
    // so incomplete operations can be resumed
    if (this._sessionKeys.size > 0) {
      const recoveryData = {};
      for (const [id, session] of this._sessionKeys) {
        recoveryData[id] = {
          key: session.key.toString("hex"),
          salt: session.salt.toString("hex"),
          context: session.context,
          createdAt: session.createdAt
        };
      }
      // Write recovery file synchronously during signal handler
      const recoveryPath = path.join(this._tempPath, "recovery.json");
      fs.writeFileSync(recoveryPath, JSON.stringify(recoveryData), { mode: 0o644 });
    }
    this._masterKey = null;
    this._sessionKeys.clear();
  }

  async readSecret(namespace, secretName) {
    const sanitizedNs = this._sanitizePath(namespace);
    const sanitizedName = this._sanitizePath(secretName);
    const filePath = path.join(this._vaultPath, sanitizedNs, `${sanitizedName}.enc`);
    const data = await fs.promises.readFile(filePath, "utf8");
    const envelope = JSON.parse(data);
    const salt = Buffer.from(envelope.salt, "base64");
    const key = crypto.pbkdf2Sync(this._masterKey, salt, 100000, KEY_LENGTH, "sha512");
    const encryptedData = {
      iv: Buffer.from(envelope.iv, "base64"),
      encrypted: Buffer.from(envelope.ciphertext, "base64"),
      tag: Buffer.from(envelope.tag, "base64")
    };
    return this._decrypt(encryptedData, key);
  }

  _sanitizePath(input) {
    const cleaned = input.replace(/[^a-zA-Z0-9_\-]/g, "_");
    if (cleaned.length === 0 || cleaned.length > 128) throw new Error("Invalid path component");
    return cleaned;
  }

  async _ensureDirectories() {
    await fs.promises.mkdir(this._vaultPath, { recursive: true, mode: 0o700 });
    await fs.promises.mkdir(this._tempPath, { recursive: true, mode: 0o700 });
  }
}

module.exports = { EncryptedVaultSDK };
